<script setup lang="ts">import{reactive,ref}from'vue';import{useRouter}from'vue-router';import{ElMessage}from'element-plus';import{register}from'../api/auth';const router=useRouter(),busy=ref(false),form=reactive({username:'',password:'',confirm:''});async function submit(){if(!/^[\w.-]{3,32}$/.test(form.username))return ElMessage.warning('用户名需为 3–32 位字母、数字、点、横线或下划线');if(form.password.length<6)return ElMessage.warning('密码至少需要 6 位');if(form.password!==form.confirm)return ElMessage.warning('两次输入的密码不一致');busy.value=true;try{await register({username:form.username,password:form.password});ElMessage.success('账号创建成功，请登录');router.push('/login')}finally{busy.value=false}}</script>
<template><div class="login-page"><section class="login-art"><div class="brand"><span class="brand-mark">F</span><span>Folio<span class="brand-light">Tree</span></span></div><div><h1>你的文件空间，<br>从这里开始。</h1><p>创建账号，开启结构清晰的文件管理体验。</p></div><small>FILE SYSTEM · STRUCTURE · INSIGHT</small></section><section class="login-box"><h2>创建账号</h2><p>注册后即可访问目录工作台</p><form @submit.prevent="submit"><div class="form-row"><label>用户名</label><input v-model.trim="form.username" class="field" placeholder="3–32 位字母或数字"></div><div class="form-row"><label>密码</label><input v-model="form.password" class="field" type="password" placeholder="至少 6 位"></div><div class="form-row"><label>确认密码</label><input v-model="form.confirm" class="field" type="password" placeholder="再次输入密码"></div><button class="btn" :disabled="busy">{{busy?'正在创建…':'创建账号'}}</button></form><div class="sub-link">已有账号？ <router-link to="/login">返回登录</router-link></div></section></div></template>
